import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Argot 0.1.2","description":"","frontmatter":{"title":"Argot 0.1.2","date":"2026-08-07T00:00:00.000Z","tag":"release"},"headers":[],"relativePath":"news/posts/2026-08-07-argot-0-1-2.md","filePath":"news/posts/2026-08-07-argot-0-1-2.md","lastUpdated":1786529726000}'),s={name:"news/posts/2026-08-07-argot-0-1-2.md"};function n(i,e,l,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>Argot 0.1.2 is on Maven Central. No API or behaviour changes — this release is about the machinery underneath, plus one thing you will actually see.</p><h2 id="generated-parsers-got-readable" tabindex="-1">Generated parsers got readable <a class="header-anchor" href="#generated-parsers-got-readable" aria-label="Permalink to &quot;Generated parsers got readable&quot;">​</a></h2><p>The parser the KSP processor writes for you now puts each parameter on its own line. The longest generated line dropped from about 130 columns to 64, so opening the generated file is no longer a horizontal scrolling exercise.</p><h2 id="the-public-api-is-now-guarded-by-the-build" tabindex="-1">The public API is now guarded by the build <a class="header-anchor" href="#the-public-api-is-now-guarded-by-the-build" aria-label="Permalink to &quot;The public API is now guarded by the build&quot;">​</a></h2><p>Every published module records its public ABI, and the build fails if it changes without the record being updated. That matters more than it sounds: code generated by an older processor has to keep compiling against a newer core, so the declarations generated parsers call are a compatibility surface even though nobody types them by hand.</p><h2 id="kotlin-stays-on-2-3-20" tabindex="-1">Kotlin stays on 2.3.20 <a class="header-anchor" href="#kotlin-stays-on-2-3-20" aria-label="Permalink to &quot;Kotlin stays on 2.3.20&quot;">​</a></h2><p>No KSP release targets Kotlin 2.4.x yet, and the two have to match. Raising Kotlin alone would leave the processor compiling against a Kotlin it was never built for, so it waits — and when it lands it will be a minor release, because annotation-style users have to apply matching versions themselves.</p><p>Full detail in the <a href="https://github.com/Derrick-Mwendwa/argot/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>.</p>',8)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
